const MODULE_PATH = '/data/adb/modules/wadbd';
const PERSIST_PATH = '/data/adb/wadbd';
const BIND_FILE = `${PERSIST_PATH}/bind_ifaces`;
const BOOT_FLAG = `${PERSIST_PATH}/enable_on_boot`;
let callbackCounter = 0;
const themes = ['light', 'dark', 'amoled'];
let currentThemeIndex = localStorage.getItem('themeIndex') ? parseInt(localStorage.getItem('themeIndex')) : 0;
let isEnvironmentSupported = true;
let showNotifications = localStorage.getItem('showNotifications') === 'true';

async function fetchWADBDVersion() {
    const versionElement = document.getElementById('wadbdVersion');
    if (!versionElement) return;
    try {
        const { stdout: moduleProp } = await exec('cat /data/adb/modules/wadbd/module.prop | grep version= | sed s/version=//g');
        versionElement.textContent = moduleProp.trim();
    } catch (error) {
        versionElement.textContent = 'Error fetching version';
    }
}

function toggleInfoDialog() {
    const dialog = document.getElementById('infoDialog');
    dialog.style.display = dialog.style.display === 'none' ? 'flex' : 'none';
    if (dialog.style.display === 'flex') fetchWADBDVersion();
}

function toggleSettingsMenu() {
    const settingsMenu = document.getElementById('settingsMenu');
    settingsMenu.style.display = settingsMenu.style.display === 'none' ? 'flex' : 'none';
}

document.addEventListener('click', function(event) {
    const settingsMenu = document.getElementById('settingsMenu');
    const settingsButton = document.querySelector('.settings-button');
    if (!settingsMenu.contains(event.target) && !settingsButton.contains(event.target)) {
        settingsMenu.style.display = 'none';
    }
});

function openLink(url) {
    if (typeof ksu !== 'undefined' && ksu.exec) {
        ksu.exec(`am start -a android.intent.action.VIEW -d "${url}"`, '{}', 'openLink_callback');
    } else {
        window.open(url, '_blank');
    }
}

function setTheme(index) {
    const theme = themes[index];
    document.body.setAttribute('data-theme', theme === 'dark' ? '' : theme);
    localStorage.setItem('themeIndex', index);
}

function toggleTheme() {
    currentThemeIndex = (currentThemeIndex + 1) % themes.length;
    setTheme(currentThemeIndex);
}

function getUniqueCallbackName(base) {
    return `${base}_${Date.now()}_${callbackCounter++}`;
}

function alert(message) {
    if (typeof ksu !== 'undefined' && ksu.toast) {
        ksu.toast(message);
    } else {
        console.log(`Toast: ${message}`);
    }
}

async function exec(command) {
    return new Promise((resolve, reject) => {
        const callbackName = getUniqueCallbackName('exec');
        window[callbackName] = (errno, stdout, stderr) => {
            resolve({ errno, stdout: stdout.trim(), stderr });
            delete window[callbackName];
        };
        try {
            ksu.exec(command, '{}', callbackName);
        } catch (error) {
            reject(error);
            delete window[callbackName];
        }
    });
}

async function initializeEnvironment() {
    try {
        if (typeof ksu === 'undefined' && typeof mmrl === 'undefined' && typeof $wadbd === 'undefined') {
            isEnvironmentSupported = false;
            showUnsupportedDialog();
            return;
        }
        if (typeof ksu === 'undefined' || !ksu.exec) {
            isEnvironmentSupported = false;
            if (typeof mmrl !== 'undefined' && typeof $wadbd !== 'undefined') {
                const ksuDialog = document.getElementById('ksuDialog');
                ksuDialog.style.display = 'flex';
                const requestKsuApiButton = document.getElementById('requestKsuApiButton');
                requestKsuApiButton.addEventListener('click', async () => {
                    try {
                        await $wadbd.requestAdvancedKernelSUAPI();
                        alert("KernelSU API access requested. Please grant access.");
                        ksuDialog.style.display = 'none';
                        initializeEnvironment();
                    } catch (error) {
                        alert("Failed to request KernelSU API access.");
                    }
                });
            }
            return;
        }
        const { errno } = await exec('id');
        isEnvironmentSupported = errno === 0;
    } catch {
        isEnvironmentSupported = false;
    }
    updateStatus();
    updateDeviceInfo();
    updateBindingList();
    updateKeyList();
}

function showUnsupportedDialog() {
    const unsupportedDialog = document.getElementById('unsupportedDialog');
    unsupportedDialog.style.display = 'flex';
}

async function updateDeviceInfo() {
    const deviceInfoDiv = document.getElementById('deviceInfo');
    if (!isEnvironmentSupported) {
        deviceInfoDiv.innerHTML = '<div class="error-message">Kernel SU API is missing. Unsupported Environment</div>';
        return;
    }
    try {
        const [
            { stdout: deviceCodename },
            { stdout: deviceName },
            { stdout: androidVersion },
            { stdout: securityPatch },
            { stdout: kernelVersion }
        ] = await Promise.all([
            exec('getprop ro.product.device'),
            exec('getprop ro.product.model'),
            exec('getprop ro.build.version.release'),
            exec('getprop ro.build.version.security_patch'),
            exec('uname -r')
        ]);
        deviceInfoDiv.innerHTML = `
            <div class="info-item">
                <span class="info-label">Device Codename :</span>
                <span class="info-value">${deviceCodename || 'Unknown'}</span>
            </div>
            <div class="info-item">
                <span class="info-label">Device Name :</span>
                <span class="info-value">${deviceName || 'Unknown'}</span>
            </div>
            <div class="info-item">
                <span class="info-label">Android Version :</span>
                <span class="info-value">${androidVersion || 'Unknown'}</span>
            </div>
            <div class="info-item">
                <span class="info-label">Security Patch :</span>
                <span class="info-value">${securityPatch || 'Unknown'}</span>
            </div>
            <div class="info-item">
                <span class="info-label">Kernel Version :</span>
                <span class="info-value">${kernelVersion || 'Unknown'}</span>
            </div>
        `;
    } catch (error) {
        deviceInfoDiv.innerHTML = '<div class="error-message">Error fetching device information</div>';
    }
}

document.addEventListener("DOMContentLoaded", function () {
    const wirelessToggle = document.getElementById("wirelessToggle");
    const portInput = document.getElementById("portInput");

    portInput.addEventListener("input", function () {
        if (this.value.length > 5) {
            this.value = this.value.slice(0, 5);
        }
        if (isValidPort(this.value.trim())) {
            localStorage.setItem('adbPort', this.value.trim());
        }
    });

    wirelessToggle.addEventListener("change", function () {
        const port = portInput.value.trim();
        if (this.checked) {
            if (!isValidPort(port)) {
                alert("Invalid port! Enter a port between 1024 and 65535.");
                this.checked = false;
            }
        }
    });
});

function isValidPort(port) {
    return port === "" || (/^\d{1,5}$/.test(port) && port >= 1024 && port <= 65535);
}

async function getBootPort() {
    try {
        const { stdout } = await exec(`cat "${BOOT_FLAG}" 2>/dev/null`);
        return stdout.trim() || null;
    } catch { return null; }
}

async function updateStatus() {
    const statusDiv = document.getElementById('statusOutput');
    if (!isEnvironmentSupported) {
        statusDiv.innerHTML = '<div class="error-message">Kernel SU API is missing. Unsupported Environment.</div>';
        setAllControlsDisabled(true);
        return;
    }
    try {
        const [
            { stdout: usbDebug },
            { stdout: wirelessPort },
            { stdout: adbdStatus },
            { stdout: adbdPid }
        ] = await Promise.all([
            exec('settings get global adb_enabled'),
            exec('getprop service.adb.tcp.port'),
            exec('getprop init.svc.adbd'),
            exec('pidof adbd')
        ]);
        const bootEnabled = await checkBootStatus();
        const bootPort = await getBootPort();
        const isWirelessEnabled = wirelessPort !== '' && wirelessPort !== '-1';

        let bindingStatus = '';
        try {
            const { stdout: bindFile } = await exec(`[ -f "${BIND_FILE}" ] && cat "${BIND_FILE}" | wc -l || echo "0"`);
            const bindCount = parseInt(bindFile.trim()) || 0;
            bindingStatus = bindCount > 0
                ? `<div class="status-item"><span class="status-label">Interface Binding : </span><span>${bindCount} target(s) restricted</span></div>`
                : `<div class="status-item"><span class="status-label">Interface Binding : </span><span>None (all interfaces open)</span></div>`;
        } catch { bindingStatus = ''; }

        statusDiv.innerHTML = `
            <div class="status-item">
                <span class="status-label">USB Debugging : </span>
                <span>${usbDebug === '1' ? 'Enabled' : 'Disabled'}</span>
            </div>
            <div class="status-item">
                <span class="status-label">Wireless ADB : </span>
                <span>${isWirelessEnabled ? `Enabled (Port ${wirelessPort})` : 'Disabled'}</span>
            </div>
            <div class="status-item">
                <span class="status-label">ADB Daemon : </span>
                <span>${adbdStatus || 'Unknown'} ${adbdStatus.trim() === 'running' ? `(PID: ${adbdPid.trim() || 'N/A'})` : ''}</span>
            </div>
            ${bindingStatus}
            <div class="status-item">
                <span class="status-label">WADBD on Boot : </span>
                <span>${bootEnabled ? `Enabled (Port ${bootPort || 'Unknown'})` : 'Not enabled'}</span>
            </div>
        `;
        document.getElementById('usbDebugToggle').checked = usbDebug === '1';
        document.getElementById('wirelessToggle').checked = isWirelessEnabled;
        document.getElementById('bootToggle').checked = bootEnabled;
        setAllControlsDisabled(false);
    } catch (error) {
        statusDiv.innerHTML = '<div class="error-message">Error fetching status</div>';
        setAllControlsDisabled(true);
    }
}

async function toggleUsbDebug(enabled) {
    if (!isEnvironmentSupported) return;
    try {
        await exec(`settings put global adb_enabled ${enabled ? '1' : '0'}`);
        updateStatus();
    } catch (error) {
        console.error('Error toggling USB debugging:', error);
    }
}

async function toggleWirelessAdb(enabled) {
    if (!isEnvironmentSupported) return;
    try {
        let port = parseInt(document.getElementById('portInput').value) || 5555;
        if (port < 1024 || port > 65535) {
            alert("Invalid port! Please enter a port between 1024 and 65535.");
            return;
        }
        await exec(`setprop service.adb.tcp.port ${enabled ? port : '-1'}`);
        await exec('stop adbd');
        await exec('start adbd');
        // Wait for adbd to start, then re-apply bindings
        if (enabled) {
            setTimeout(async () => {
                await exec(`test -f "${BIND_FILE}" && /system/bin/wadbd bind-status`).catch(() => {});
            }, 1500);
        }
        if (enabled && showNotifications) {
            await exec(`su -lp 2000 -c "cmd notification post -S bigtext -t 'WADBD' 'Tag' 'Wireless ADBD Enabled on port ${port} !!'" > /dev/null 2>&1`);
        }
        updateStatus();
    } catch (error) {
        console.error('Error toggling wireless ADB:', error);
    }
}

async function checkBootStatus() {
    try {
        const { stdout } = await exec(`[ -f "${BOOT_FLAG}" ] && echo "1" || echo "0"`);
        return stdout === '1';
    } catch { return false; }
}

async function toggleBoot(enabled) {
    if (!isEnvironmentSupported) return;
    try {
        if (enabled) {
            let port = parseInt(document.getElementById('portInput').value) || 5555;
            if (port < 1024 || port > 65535) {
                alert("Invalid port! Please enter a port between 1024 and 65535.");
                return;
            }
            const { errno, stderr } = await exec(`/system/bin/wadbd enable-on-boot ${port}`);
            if (errno !== 0) {
                alert(`Failed to enable on boot: ${stderr}`);
            }
        } else {
            const { errno, stderr } = await exec('/system/bin/wadbd disable-on-boot');
            if (errno !== 0) {
                alert(`Failed to disable on boot: ${stderr}`);
            }
        }
        updateStatus();
    } catch (error) {
        console.error('Error toggling boot status:', error);
    }
}

function setAllControlsDisabled(disabled) {
    ['usbDebugToggle', 'wirelessToggle', 'bootToggle', 'portInput', 'changePortBtn'].forEach(id => {
        const element = document.getElementById(id);
        if (element) element.disabled = disabled;
    });
}

document.getElementById('usbDebugToggle').addEventListener('change', (e) => { toggleUsbDebug(e.target.checked); });
document.getElementById('wirelessToggle').addEventListener('change', (e) => { toggleWirelessAdb(e.target.checked); });
document.getElementById('bootToggle').addEventListener('change', (e) => { toggleBoot(e.target.checked); });

document.getElementById('changePortBtn').addEventListener('click', async () => {
    const wirelessEnabled = document.getElementById('wirelessToggle').checked;
    const bootEnabled = document.getElementById('bootToggle').checked;
    if (wirelessEnabled) await toggleWirelessAdb(true);
    if (bootEnabled) await toggleBoot(true);
});

async function updateConnectionInfo() {
    const connectionInfoDiv = document.getElementById('connectionInfo');
    if (!isEnvironmentSupported) {
        connectionInfoDiv.innerHTML = '<div class="error-message">Kernel SU API is missing. Unsupported Environment</div>';
        return;
    }
    try {
        const { stdout: wirelessPort } = await exec('getprop service.adb.tcp.port');
        const isWirelessEnabled = wirelessPort !== '' && wirelessPort !== '-1';
        if (!isWirelessEnabled) {
            connectionInfoDiv.innerHTML = '<div class="info-message">Wireless ADB is currently disabled. Enable it to see connection commands.</div>';
            return;
        }
        const { stdout: ipInfo } = await exec('ip -f inet addr show');
        const ipMatches = [...ipInfo.matchAll(/inet (\d+\.\d+\.\d+\.\d+).*(?:wlan|rmnet|eth|rndis)/g)];
        if (ipMatches.length === 0) {
            connectionInfoDiv.innerHTML = '<div class="warning-message">No valid network interfaces found. Make sure you\'re connected to a network.</div>';
            return;
        }
        let html = '<div class="connection-section"><div class="connection-header">Available Connection Commands:</div><div class="network-interfaces">';
        ipMatches.forEach(match => {
            const ip = match[1];
            html += `<div class="command-group"><div class="interface-info">Interface IP: ${ip}</div><div class="command-box"><code>adb connect ${ip}:${wirelessPort}</code><button class="copy-button" onclick="copyToClipboard('adb connect ${ip}:${wirelessPort}')">Copy</button></div></div>`;
        });
        html += '</div><div class="connection-note">Note: Make sure ADB is installed on your computer and both devices are on the same network.</div></div>';
        connectionInfoDiv.innerHTML = html;
    } catch (error) {
        connectionInfoDiv.innerHTML = '<div class="error-message">Error fetching connection information</div>';
    }
}

function copyToClipboard(text) {
    navigator.clipboard.writeText(text).catch(err => { console.error('Failed to copy: ', err); });
}

// ─── Interface Binding UI ────────────────────────────────────────

async function updateBindingList() {
    const bindingList = document.getElementById('bindingList');
    if (!isEnvironmentSupported || !bindingList) return;

    try {
        const { stdout: interfacesRaw } = await exec('ip link show | grep -E "^[0-9]+:" | awk -F": " \'{print $2}\'');
        const interfaces = interfacesRaw.split('\n')
            .filter(i => i && i !== 'lo' && !i.match(/^(dummy|ifb|gre|gretap|erspan|tunl|sit|ip6|ip_vti|ccmni|miw|p2p)/))
            .map(i => i.trim().split('@')[0]);

        // Get current bindings
        let boundIfaces = [];
        try {
            const { stdout: bindData } = await exec(`[ -f "${BIND_FILE}" ] && cat "${BIND_FILE}" || echo ""`);
            boundIfaces = bindData.split('\n').filter(i => i.trim()).map(i => i.trim());
        } catch { boundIfaces = []; }

        // Get current ADB port
        const { stdout: port } = await exec('getprop service.adb.tcp.port');
        const adbActive = port !== '' && port !== '-1';

        let html = '';

        // Preset: Mesh VPN Subnet
        const isZtBound = boundIfaces.includes('100.96.0.0/12') || boundIfaces.includes('mesh');
        html += `<div class="setting-item" style="border-left: 3px solid #f38020; padding-left: 8px;">
            <div class="binding-interface-info">
                <span class="binding-iface-name">Private Mesh Subnet <small style="opacity:0.75">(100.96.0.0/12)</small></span>
                <span class="binding-iface-detail">Accepts mesh IPs regardless of dynamic tunnel interface</span>
            </div>
            <label class="toggle-switch">
                <input type="checkbox" class="bind-toggle" data-iface="100.96.0.0/12" ${isZtBound ? 'checked' : ''} ${!adbActive ? 'disabled' : ''}>
                <span class="toggle-slider"></span>
            </label>
        </div>`;

        // Preset: All VPN Tunnels wildcard
        const isTunWildcardBound = boundIfaces.includes('tun+');
        html += `<div class="setting-item" style="border-left: 3px solid #4caf50; padding-left: 8px;">
            <div class="binding-interface-info">
                <span class="binding-iface-name">All VPN Tunnels <small style="opacity:0.75">(tun+)</small></span>
                <span class="binding-iface-detail">Matches tun0, tun1, etc. dynamically</span>
            </div>
            <label class="toggle-switch">
                <input type="checkbox" class="bind-toggle" data-iface="tun+" ${isTunWildcardBound ? 'checked' : ''} ${!adbActive ? 'disabled' : ''}>
                <span class="toggle-slider"></span>
            </label>
        </div>`;

        for (const iface of interfaces) {
            const state = await getInterfaceState(iface);
            const ip = await getInterfaceIP(iface);
            const isBound = boundIfaces.includes(iface);
            const isUp = state === 'UP';

            let tag = '';
            if (ip && ip.startsWith('100.96.')) tag = ' [Mesh VPN]';
            else if (ip && ip.startsWith('100.')) tag = ' [Tailscale]';
            else if (iface.startsWith('tun')) tag = ' [VPN]';
            else if (iface.startsWith('wlan')) tag = ' [Wi-Fi]';

            html += `<div class="setting-item">
                <div class="binding-interface-info">
                    <span class="binding-iface-name">${iface} <small style="opacity:0.7">${tag}</small></span>
                    <span class="binding-iface-detail">${isUp ? '<span style="color:#4caf50">UP</span>' : '<span style="color:#f44336">DOWN</span>'} ${ip || ''}</span>
                </div>
                <label class="toggle-switch">
                    <input type="checkbox" class="bind-toggle" data-iface="${iface}" ${isBound ? 'checked' : ''} ${!adbActive ? 'disabled' : ''}>
                    <span class="toggle-slider"></span>
                </label>
            </div>`;
        }

        if (!adbActive) {
            html += '<div class="info-message" style="margin-top:8px">Enable Wireless ADB first to manage interface bindings.</div>';
        } else if (boundIfaces.length > 0) {
            html += `<div class="binding-note">ADB is restricted to ${boundIfaces.length} target(s). Only these interfaces/subnets can accept ADB connections.</div>`;
        } else {
            html += '<div class="binding-note">No restrictions — ADB accepts connections on ALL interfaces.</div>';
        }

        bindingList.innerHTML = html;

        // Attach event listeners to toggles
        document.querySelectorAll('.bind-toggle').forEach(toggle => {
            toggle.addEventListener('change', async function(e) {
                const target = this.dataset.iface;
                if (this.checked) {
                    const { errno, stderr } = await exec(`/system/bin/wadbd bind ${target}`);
                    if (errno !== 0) {
                        alert(`Failed to bind ${target}: ${stderr}`);
                        this.checked = false;
                    } else {
                        alert(`ADB bound to ${target}`);
                    }
                } else {
                    const { errno, stderr } = await exec(`/system/bin/wadbd unbind ${target}`);
                    if (errno !== 0) {
                        alert(`Failed to unbind ${target}: ${stderr}`);
                        this.checked = true;
                    } else {
                        alert(`${target} unbound`);
                    }
                }
                updateStatus();
                updateBindingList();
                updateConnectionInfo();
            });
        });

    } catch (error) {
        bindingList.innerHTML = '<div class="error-message">Error fetching interfaces</div>';
    }
}

async function getInterfaceState(iface) {
    try {
        const { stdout } = await exec(`ip link show ${iface} | grep -oE 'state [A-Z]+' | awk '{print $2}'`);
        return stdout.trim();
    } catch { return 'UNKNOWN'; }
}

async function getInterfaceIP(iface) {
    try {
        const { stdout } = await exec(`ip -f inet addr show ${iface} | grep -oE 'inet [0-9]+\\.[0-9]+\\.[0-9]+\\.[0-9]+' | head -1 | awk '{print $2}'`);
        return stdout.trim();
    } catch { return ''; }
}

// ─── Init ─────────────────────────────────────────────────────────

window.onload = () => {
    setTheme(currentThemeIndex);
    initializeEnvironment();
    const notificationToggle = document.getElementById('notificationToggle');
    notificationToggle.checked = showNotifications;

    const savedPort = localStorage.getItem('adbPort');
    if (savedPort) {
        document.getElementById('portInput').value = savedPort;
    }
};

document.getElementById('notificationToggle').addEventListener('change', async (e) => {
    showNotifications = e.target.checked;
    localStorage.setItem('showNotifications', showNotifications);
    try {
        await exec(showNotifications ? 'wadbd notify on' : 'wadbd notify off');
    } catch (_) {}
});

// Refresh status and binding list periodically
setInterval(() => {
    updateStatus();
    updateConnectionInfo();
}, 5000);

// Refresh key list as well
setInterval(() => {
    if (isEnvironmentSupported) updateKeyList();
}, 30000);

// Refresh binding list less frequently (interface state changes are rare)
setInterval(() => {
    updateBindingList();
}, 15000);
